 **/
const TypeDetailsForm: FC = () => {
  const kitCommands = useKitCommands();
  const type = useType(undefined, undefined, true) as Type;

  const updateTypeField = (diff: any) => {
    kitCommands?.updateType(type.guid, diff);
  };

  return (
    <>
      <TreeRow>
        <Input lazy id="compose.sketchpad.app.type.panel.details.section.type.name" value={type.name} onLazyChange={(value) => updateTypeField({ name: value })} showLabel />
      </TreeRow>
      <TreeRow>
