            icon: <AddIcon />,
            onClick: () => {
              const origin = "compose.sketchpad.app.type.panel.details.connectors.add";
              applyDiff({
                connectors: {
                  added: [
                    {
                      guid: guid(),
                      t: 0,
                      point: { x: 0, y: 0, z: 0 },
                      direction: { x: 0, y: 0, z: 1 },
                    },
                  ],
                },
              });
            },
            id: "compose.sketchpad.common.add",
          },
        ]}
      >
        {hasPorts && (
          <TreeRow>
            <Ring
              id="compose.sketchpad.app.type.panel.details.section.connectors.ring"
              orbs={(type.connectors || []).map((connector: any) => {
                const isSelected = selection?.connectors?.includes(connector.guid) || false;
                return {
                  id: connector.guid,
                  t: connector.t ?? 0,
                  selected: isSelected,
                  hovered: hover?.connector === connector.guid,
                  disabled: !isSelected,
                };
              })}
              onOrbChange={(orbId, _oldT, newT) => {
                updatePort(orbId, { t: newT });
              }}
              onOrbSelect={(orbId) => {
                if (!setSelection) return;
                setSelection({
                  ...(selection || {}),
                  connectors: [orbId],
                  models: [],
                });
              }}
              onOrbHoverChange={(orbId, hovered) => {
                if (hovered) hoverPort?.(orbId);
                else clearHover?.();
              }}
              showLabel
            />
          </TreeRow>
        )}
        {hasPorts && (
          <SortableTreeItems
            items={(type.connectors || []).map((connector: any, index: number) => ({
