                        onLazyChange={(value: string) => {
                          updatePort(connector.guid, { description: value });
                        }}
                        showLabel
                      />
                    </TreeRow>
                    <TreeItem id="compose.sketchpad.app.type.connectorPoint">
                      <TreeRow>
                        <Stepper
                          id="compose.sketchpad.app.type.panel.details.section.connectors.point.x"
                          value={connector.point.x}
                          onChange={(value: number) => {
                            updatePort(connector.guid, { point: { x: value } });
                          }}
                          step={0.1}
                        />
                      </TreeRow>
                      <TreeRow>
                        <Stepper
                          id="compose.sketchpad.app.type.panel.details.section.connectors.point.y"
                          value={connector.point.y}
                          onChange={(value: number) => {
                            updatePort(connector.guid, { point: { y: value } });
                          }}
                          step={0.1}
                        />
                      </TreeRow>
                      <TreeRow>
                        <Stepper
                          id="compose.sketchpad.app.type.panel.details.section.connectors.point.z"
                          value={connector.point.z}
                          onChange={(value: number) => {
